"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5890],{68024:e=>{e.exports=JSON.parse('{"functions":[{"name":"hide","desc":"Detaches as many stale placements as the frame allows. Runs in\\n`Phases.PreUpdate`, ahead of everything that builds.\\n\\nAlways hides at least one placement per pass, so the queue cannot stall.","params":[{"name":"world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":45,"path":"src/main/server/systems/maze/hide.luau"}}],"properties":[],"types":[],"name":"hide","desc":"Detaches placements a few at a time. Any placement whose entity has\\n`Rendered` but no longer has `Render` gets its model unparented, under a frame\\nbudget.\\n\\nThe model is detached, not destroyed \u2014 it stays on the entity\'s\\n`PlacementModel` so walking back into range only has to re-admit it rather\\nthan rebuild it.\\n\\nEntities tagged `Processing` are skipped: yanking a model out while\\n[slowParent] is still streaming it in would strand its remaining children\\ndetached forever.\\n\\n**It runs before everything that builds, and that ordering is the point.**\\nHiding is the one stage where going slower is measurably worse: this engine\\nbills for instances *resident* in the world each frame, not for the parent\\nwrite that removes them, so a drawn-out hide keeps paying for the very props\\nit is trying to stop paying for. Spreading a chunk detach across frames\\nmeasured mean 17.89ms against 10.39ms for doing it at once. Giving hide first\\nclaim on the frame\'s allowance is how that finding is honoured now that every\\nstage shares one budget.","tags":["server-system"],"realm":["Server"],"source":{"line":27,"path":"src/main/server/systems/maze/hide.luau"}}')}}]);